<?php
// lot_positions.php
// OOP approach for lot positioning - standard size, only positions vary

// Per-garden/sector lot dimensions only (no global default)
class LotConfig {
    // Edit values below to change sizes per garden/sector.
    // Any garden/sector not listed will have no implicit size.
    private static $SIZES_BY_SECTOR = [
        // 'Garden Name' => [ 'Sector' => ['width' => <number>, 'height' => <number>], ... ]
        // Examples (feel free to change):
        'Joy Garden' => [
            'A' => ['width' => 24, 'height' => 45],
            'B' => ['width' => 26, 'height' => 46],
            'C' => ['width' => 20, 'height' => 49],
            'D' => ['width' => 20, 'height' => 49],
        ],
        'Peace Garden' => [
            'A' => ['width' => 23, 'height' => 55],
            'B' => ['width' => 24, 'height' => 48],
            'C' => ['width' => 23, 'height' => 58],
            'D' => ['width' => 22, 'height' => 56],
        ],
        'Hope Garden' => [
            'A' => ['width' => 48, 'height' => 20],
            'B' => ['width' => 52, 'height' => 20],
            'C' => ['width' => 49, 'height' => 20],
            'D' => ['width' => 49, 'height' => 21],
        ],
        'Faith Garden' => [
            'A' => ['width' => 67, 'height' => 22],
            'B' => ['width' => 67, 'height' => 23],
            'C' => ['width' => 69, 'height' => 20],
            'D' => ['width' => 59, 'height' => 27],
        ],
        'Love Garden' => [
            'A' => ['width' => 30, 'height' => 67],
            'B' => ['width' => 26, 'height' => 57],
            'C' => ['width' => 23, 'height' => 57],
            'D' => ['width' => 25, 'height' => 65],
        ],
    ];

    // Returns size for specific garden/sector or null if undefined
    public static function getSectorSize(?string $garden, ?string $sector) {
        if ($garden && $sector && isset(self::$SIZES_BY_SECTOR[$garden][$sector])) {
            return self::$SIZES_BY_SECTOR[$garden][$sector];
        }
        return null;
    }
}

